import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";

const PatientLogin = () => {
  const navigate = useNavigate();

  const [mobile, setMobile] = useState("");
  const [otp, setOtp] = useState("");
  const [step, setStep] = useState(1);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);



  // STEP 1: Request OTP from backend
  const handleSendOtp = async (e) => {
    e.preventDefault();
    if (mobile.length !== 10) {
        setError("Please enter a valid 10-digit mobile number.");
        return;
    }

    setError("");
    setLoading(true);
    try {
      const res = await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/users/patient-send-otp`, { 
        mobileNumber: mobile // Matches backend req.body key
      });
      
      setStep(2); // Move to OTP input
    } catch (err) {
      setError(err.response?.data?.message || "User not found or Server error.");
    } finally {
      setLoading(false);
    }
  };

  // STEP 2: Verify OTP and get Token
  const handleVerifyOtp = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const res = await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/users/login-verify-otp`, { 
        mobileNumber: mobile, 
        otp: otp 
      });

      // Store token and user data
      localStorage.setItem("token", res.data.token);
      localStorage.setItem("user", JSON.stringify(res.data.user));
      localStorage.setItem("userToken", res.data.token);
      localStorage.setItem("userId", res.data.user.id);
      window.dispatchEvent(new Event("userLogin"));
      console.log("result",res.data);
      

      navigate("/user-dashboard");
    } catch (err) {
      setError(err.response?.data?.message || "Invalid OTP. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <section className="account d-flex" style={{ height: "100vh" }}>
        <div className="account__left d-md-flex d-none flx-align section-bg position-relative z-index-1 overflow-hidden">
          <div className="account-thumb">
            <img src="assets/images/services/Login.png" alt="Login" loading="lazy" />
            <div className="statistics animation bg-main text-center">
              <span className="statistics__text text-white font-14">
                Verified <br /> Healthcare <br /> Centre
              </span>
            </div>
          </div>
        </div>

        <div className="account__right padding-y-120 flx-align">
          <div className="account-content">
            <Link to="/" className="logo">
              <img src="assets/images/logo/BHARATLOGO-01.png" alt="Logo" className="white-version" />
              <img src="assets/images/logo/BHARATLOGO-01.png" alt="Logo" className="dark-version" />
            </Link>

            <h4 className="account-content__title mb-35 text-capitalize" style={{ textAlign: "center" }}>
              {step === 1 ? "Login Account" : "Verify OTP"}
            </h4>

            {error && <div className="alert alert-danger">{error}</div>}

            <form onSubmit={step === 1 ? handleSendOtp : handleVerifyOtp}>
              <div className="row gy-4">
                {step === 1 ? (
                  <div className="col-12">
                    <label className="form-label mb-2 font-18 font-heading fw-600" style={{ fontFamily: "inter" }}>
                      Mobile Number
                    </label>
                    <div className="position-relative">
                      <input
                        type="tel"
                        className="common-input common-input--bg common-input--withIcon"
                        placeholder="Enter mobile number"
                        required
                        value={mobile}
                        onChange={(e) => setMobile(e.target.value.replace(/\D/g, ""))}
                        maxLength={10}
                      />
                      <span className="input-icon">
                        <img src="assets/images/icons/envelope-icon.svg" alt="icon" />
                      </span>
                    </div>
                  </div>
                ) : (
                  <div className="col-12">
                    <label className="form-label mb-2 font-18 font-heading fw-600" style={{ fontFamily: "inter" }}>
                      Enter OTP sent to {mobile}
                    </label>
                    <div className="position-relative">
                      <input
                        type="tel"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        className="common-input common-input--bg common-input--withIcon"
                        placeholder="Enter 6-digit OTP"
                        required
                        value={otp}
                        onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))}
                        maxLength={6}
                      />
                      <span className="input-icon">
                        <img src="assets/images/icons/lock-icon.svg" alt="icon" />
                      </span>
                    </div>
                    <button 
                      type="button" 
                      className="btn text-main p-0 mt-2 font-14 text-decoration-underline"
                      onClick={() => setStep(1)}
                    >
                      Change Mobile Number?
                    </button>
                  </div>
                )}

                <div className="col-12">
                  <button type="submit" className="btn btn-main btn-lg w-100 pill" disabled={loading}>
                    {loading ? "Processing..." : step === 1 ? "Send OTP" : "Verify & Sign In"}
                  </button>
                </div>

                <div className="col-sm-12 mb-0 text-center">
                   <p className="text font-14">
                      Not Registered?{" "}
                      <Link className="link text-main text-decoration-underline fw-500" to="/user-register">
                        Register
                      </Link>
                    </p>
                </div>
              </div>
            </form>
          </div>
        </div>
      </section>
    </>
  );
};

export default PatientLogin;